SELECT * FROM exercises WHERE workout_id IN
#{workoutDbId}
ORDER BY workout_id ASC, id ASC

SELECT e.* FROM exercises e INNER JOIN workouts w ON w.id = e.workout_id WHERE w.user_id = #{userId} AND w.status = 'COMPLETED' AND e.weight IS NOT NULL AND e.weight > 0 AND e.name IN
#{name}
ORDER BY w.date DESC, w.id DESC, e.id DESC
